const results = await browserjs(tabId, () => {
  // Let's grab product titles and prices
  const items = [];
  const cards = document.querySelectorAll('[data-test="@web/site-top-of-funnel/ProductCardWrapper"]');
  if (cards.length > 0) {
    cards.forEach(card => {
      const title = card.querySelector('[data-test="product-title"]')?.textContent?.trim();
      const price = card.querySelector('[data-test="current-price"]')?.textContent?.trim();
      items.push({ title, price });
    });
  } else {
    // fallback general query
    const productElements = document.querySelectorAll('a[data-test="product-title"]');
    productElements.forEach(el => {
      const title = el.textContent?.trim();
      const container = el.closest('[data-test*="product"]') || el.parentElement;
      const price = container?.textContent?.match(/\$\d+\.\d{2}/)?.[0];
      items.push({ title, price });
    });
  }
  return {
    url: window.location.href,
    title: document.title,
    count: items.length,
    items: items.slice(0, 20)
  };
});
