const tabId = 118779795;

const urls = [
  "https://www.target.com/p/california-pizza-kitchen-thin-crust-frozen-four-cheese-pizza-13-5oz/-/A-17093512",
  "https://www.target.com/p/gluten-free-cauliflower-crust-four-cheese-frozen-pizza-good-38-gather-8482/-/A-78666207",
  "https://www.target.com/p/gluten-free-traditional-crust-frozen-cheese-pizza-21-1oz-good-38-gather-8482/-/A-87791308",
  "https://www.target.com/p/digiorno-wood-fired-four-cheese-frozen-pizza-14-6oz/-/A-94415303",
  "https://www.target.com/p/digiorno-rising-crust-four-cheese-frozen-pizza-24-6oz/-/A-90930510"
];

const results = [];
for (const url of urls) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 5000 }).catch(e => console.log(e.message));
  const res = await browserjs(tabId, () => {
    const title = document.querySelector('h1')?.innerText?.trim();
    const price = document.querySelector('[data-test="product-price"]')?.innerText?.trim();
    const text = document.body.innerText;
    const isVeg = text.toLowerCase().includes('vegetarian');
    const isCheese = text.toLowerCase().includes('cheese');
    const isFrozen = text.toLowerCase().includes('frozen');
    // Look for dietary claims or highlights
    const highlights = Array.from(document.querySelectorAll('[data-test*="highlight"], [data-test*="spec"]')).map(el => el.innerText.trim());
    return { title, price, isVeg, isCheese, isFrozen, highlights: highlights.slice(0, 5) };
  });
  results.push({ url, ...res });
}
console.log("Product check results:", JSON.stringify(results, null, 2));

