const dietTypeBtn = await browserjs(tabId, () => {
  const btns = Array.from(document.querySelectorAll('button')).filter(b => b.innerText.trim() === 'Diet Type');
  return btns.length > 0 ? { text: btns[0].innerText, className: btns[0].className } : null;
});
console.log("Diet Type button:", dietTypeBtn);

// Also let's inspect all products currently listed on this category page without filters first
const products = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('h3')).map(h => {
    const link = h.closest('a') || h.querySelector('a') || h.parentElement?.querySelector('a');
    const container = h.closest('div[class*="styles__ProductCard"]') || h.closest('div[class*="styles"]') || h.parentElement;
    const text = container?.innerText || "";
    const priceMatch = text.match(/\$(\d+\.\d{2})/);
    return {
      title: h.innerText.trim(),
      price: priceMatch ? priceMatch[0] : null,
      priceVal: priceMatch ? parseFloat(priceMatch[1]) : null,
      href: link?.href || null,
      textSnippet: text.replace(/\n+/g, ' | ').slice(0, 150)
    };
  }).filter(item => item.title && item.priceVal !== null);
  return headings;
});
console.log(`Found ${products.length} cheese pizzas:`);
