await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 5000 }).catch(e => console.log(e.message));

const cpkFourCheese = await browserjs(tabId, () => {
  const breadcrumbs = Array.from(document.querySelectorAll('nav[aria-label="Breadcrumbs"] a, nav[aria-label="Breadcrumbs"] li')).map(el => el.innerText.trim());
  const h1 = document.querySelector('h1')?.innerText?.trim();
  const price = document.body.innerText.match(/\$7\.49/)?.[0];
  return { breadcrumbs, h1, price };
});
console.log("CPK Four Cheese info:", cpkFourCheese);

